<?php declare(strict_types=1);namespace App\Core;final class Totp{private const _1u3wd='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';public static function generateSecret(int $k=20):string{return self::base32Encode(random_bytes($k));}public static function code(string $c,?int $E=null,int $H=30,int $y=6):string{$C=(int)floor(($E??time())/$H);$l=self::base32Decode($c);$e=pack('N*',0).pack('N*',$C);$W=hash_hmac('sha1',$e,$l,true);$G=ord($W[19])&0xf;$f=(ord($W[$G])&0x7f)<<24|(ord($W[$G+1])&0xff)<<16|(ord($W[$G+2])&0xff)<<8|ord($W[$G+3])&0xff;return str_pad((string)($f%10**$y),$y,'0',STR_PAD_LEFT);}public static function verify(string $k,string $i,int $o=1):bool{$i=preg_replace('/\D/','',$i)??'';if(strlen($i)!==6){return false;}$m=time();for($s=-$o;$s<=$o;$s++){if(hash_equals(self::code($k,$m+$s*30),$i)){return true;}}return false;}public static function uri(string $i,string $q,string $Q='ToutPVR'):string{return'otpauth://totp/'.rawurlencode($Q).':'.rawurlencode($q).'?secret='.$i.'&issuer='.rawurlencode($Q).'&algorithm=SHA1&digits=6&period=30';}public static function base32Encode(string $T):string{$b='';foreach(str_split($T)as $d){$b.=str_pad(decbin(ord($d)),8,'0',STR_PAD_LEFT);}$f='';foreach(str_split($b,5)as $J){$f.=self::_1u3wd[bindec(str_pad($J,5,'0',STR_PAD_RIGHT))];}return $f;}public static function base32Decode(string $b):string{$b=strtoupper(preg_replace('/[^A-Za-z2-7]/','',$b)??'');$L='';foreach(str_split($b)as $d){$L.=str_pad(decbin(strpos(self::_1u3wd,$d)),5,'0',STR_PAD_LEFT);}$l='';foreach(str_split($L,8)as $F){if(strlen($F)===8){$l.=chr(bindec($F));}}return $l;}}